@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#54f5d0;--blue:#71caff;--ink:#071018;--muted:#8da5b3}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);font-family:'Space Grotesk',sans-serif}#game{position:fixed;inset:0}canvas{display:block;width:100%;height:100%;touch-action:none}.shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(4,12,19,.78) 0%,rgba(4,12,19,.1) 23%,transparent 53%,rgba(3,10,16,.48) 100%)}.topbar{position:absolute;top:0;left:0;right:0;padding:24px 34px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.brand{display:flex;gap:12px;align-items:center}.brand-icon{width:37px;height:37px;border:1px solid #54f5d088;border-radius:11px;display:grid;place-items:center;color:var(--cyan);font-size:19px;box-shadow:0 0 24px #54f5d022;background:#071018aa}.brand-text{font-size:11px;letter-spacing:.23em;color:var(--cyan);font-weight:600}.brand-sub{font-family:'DM Mono',monospace;font-size:9px;color:#8298a7;letter-spacing:.15em;margin-top:3px}.hud{display:flex;gap:10px}.pill{min-width:106px;background:#071018bb;border:1px solid #ffffff1a;border-radius:12px;padding:9px 13px;backdrop-filter:blur(10px)}.pill-label{font:9px 'DM Mono',monospace;color:#8298a7;letter-spacing:.16em}.pill-value{font-size:17px;font-weight:600;margin-top:3px;color:#effaf8}.shard-dots{display:flex;gap:5px;margin-top:8px}.dot{width:8px;height:8px;border:1px solid #66818d;border-radius:50%}.dot.on{background:var(--cyan);border-color:var(--cyan);box-shadow:0 0 9px var(--cyan)}.mission{position:absolute;left:5.2%;top:23%;pointer-events:none;max-width:330px}.eyebrow{font:10px 'DM Mono',monospace;color:#a6bbc4;letter-spacing:.16em;display:flex;align-items:center;gap:8px}.live{width:6px;height:6px;background:var(--cyan);border-radius:50%;box-shadow:0 0 10px var(--cyan)}h1{font-size:clamp(34px,4vw,56px);line-height:1.04;letter-spacing:-.06em;margin:15px 0 9px;color:#f1faf9;font-weight:600}h1 em{font-style:normal;color:var(--cyan)}.mission p{font-size:13px;line-height:1.55;color:#a5bac4;max-width:275px;margin:0}.bottom-ui{position:absolute;left:34px;bottom:25px;display:flex;align-items:center;gap:25px;pointer-events:none}.controls-card{display:flex;gap:13px;align-items:center;padding:11px 15px;border:1px solid #ffffff1c;background:#071018bf;backdrop-filter:blur(12px);border-radius:13px}.control-keys{display:flex;align-items:center;flex-direction:column;gap:3px}.control-keys div{display:flex;gap:3px}.control-keys span{font:10px 'DM Mono',monospace;color:#d9e8e9;min-width:19px;height:19px;text-align:center;padding-top:3px;border:1px solid #ffffff28;border-radius:4px;background:#ffffff0b}.controls-card b{display:block;font-size:9px;letter-spacing:.12em;color:#e5f1f0}.controls-card small{display:block;font:8px 'DM Mono',monospace;color:#8298a7;margin-top:4px}.hint{display:flex;align-items:center;gap:9px;color:#8da5b3;font-size:10px;line-height:1.5}.hint b{color:#d7e5e6;font-weight:500}.hint-icon{font-size:19px;color:var(--cyan)}.corner-note{position:absolute;right:30px;bottom:28px;font:9px 'DM Mono',monospace;letter-spacing:.14em;color:#91a5ad;pointer-events:none}.corner-note span{color:var(--cyan);font-size:8px;margin:0 5px}.modal{position:absolute;inset:0;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 50%,#06121b35,#040b12a8);transition:opacity .3s,visibility .3s}.modal.hidden{opacity:0;visibility:hidden;pointer-events:none}.modal-card{text-align:center;width:min(410px,calc(100vw - 36px));padding:37px 38px 29px;background:linear-gradient(145deg,#10212adf,#071018eF);border:1px solid #b1fff028;border-radius:21px;box-shadow:0 24px 100px #0009,0 0 70px #54f5d010;backdrop-filter:blur(20px)}.modal-kicker{font:9px 'DM Mono',monospace;letter-spacing:.2em;color:var(--cyan)}.modal-title{font-size:39px;font-weight:600;letter-spacing:-.055em;color:#f4fbfa;margin:11px 0 7px}.modal-card p{color:#a7bac2;font-size:13px;line-height:1.65;margin:0 0 23px}.modal-card button{border:0;border-radius:9px;background:var(--cyan);color:#082019;font:700 11px 'Space Grotesk',sans-serif;letter-spacing:.11em;padding:14px 22px;min-width:160px;cursor:pointer;box-shadow:0 0 25px #54f5d02d;transition:.18s}.modal-card button:hover{transform:translateY(-2px);box-shadow:0 0 35px #54f5d05c}.modal-card button span{font-size:15px;margin-left:12px}.modal-note{font:8px 'DM Mono',monospace;color:#77909c;letter-spacing:.1em;margin-top:20px}.toast{position:absolute;top:118px;left:50%;transform:translate(-50%,-10px);padding:10px 16px;border:1px solid #54f5d066;border-radius:10px;color:#dcfff5;background:#071a1ddd;font:10px 'DM Mono',monospace;letter-spacing:.08em;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none;position:absolute;bottom:22px;right:18px;pointer-events:auto;align-items:flex-end;gap:12px}.touch-controls>div{display:grid;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(2,44px);gap:4px}.touch-controls button{border:1px solid #d5fff044;background:#071018a8;color:#e9ffff;border-radius:12px;width:44px;height:44px;font-size:15px;touch-action:none;backdrop-filter:blur(8px)}.touch-controls [data-dir=up]{grid-column:2}.touch-controls [data-dir=left]{grid-column:1;grid-row:2}.touch-controls [data-dir=down]{grid-column:2;grid-row:2}.touch-controls [data-dir=right]{grid-column:3;grid-row:2}.touch-controls button.active{background:#54f5d044;border-color:var(--cyan)}.touch-controls button.boost{height:56px;width:56px;color:var(--cyan);font-size:23px;border-color:#54f5d077}.modal:not(.hidden)~.touch-controls{display:none}
@media(max-width:700px){.topbar{padding:16px 14px;align-items:flex-start}.brand{gap:8px}.brand-icon{width:32px;height:32px}.brand-text{font-size:9px}.brand-sub{font-size:7px}.hud{gap:5px}.pill{min-width:63px;padding:7px 8px;border-radius:9px}.pill-label{font-size:7px;letter-spacing:.09em}.pill-value{font-size:13px}.shards{min-width:72px}.shard-dots{margin-top:7px}.mission{top:auto;bottom:138px;left:18px;max-width:220px}h1{font-size:36px;margin:8px 0}.mission p{font-size:11px;max-width:210px}.bottom-ui{left:14px;bottom:18px}.controls-card{display:none}.hint{display:none}.corner-note{display:none}.touch-controls{display:flex}.toast{top:88px;font-size:9px}.modal-card{padding:29px 24px 24px}.modal-title{font-size:34px}}
@media(max-height:500px) and (min-width:701px){.mission{top:21%}.bottom-ui{bottom:12px}.topbar{padding-top:14px}.modal-card{padding:22px 30px}.modal-title{font-size:32px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color('#071018');scene.fog=new THREE.FogExp2('#071018',.018);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120);camera.position.set(0,25,32);camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;mount.prepend(renderer.domElement);
scene.add(new THREE.HemisphereLight(0x9bd5de,0x101920,2));const key=new THREE.DirectionalLight(0xd8fff5,3.2);key.position.set(-8,18,8);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-24;key.shadow.camera.right=24;key.shadow.camera.top=20;key.shadow.camera.bottom=-20;scene.add(key);const cyanLight=new THREE.PointLight(0x44f5d0,38,27,2);cyanLight.position.set(-13,6,9);scene.add(cyanLight);const amberLight=new THREE.PointLight(0xff754f,22,18,2);amberLight.position.set(13,5,-8);scene.add(amberLight);
const mat=(color,roughness=.55,metalness=.1,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:ei});
const floorMat=mat('#14232a',.82,.35), trimMat=mat('#273a40',.35,.72), cyanMat=mat('#54f5d0',.25,.25,'#30f2c1',1.8), orangeMat=mat('#ff714f',.28,.2,'#ff4328',1.6), steel=mat('#344b55',.3,.8), ballMat=mat('#c5f6ef',.19,.78,'#143c3c',.4);
const floor=new THREE.Mesh(new THREE.BoxGeometry(37,.55,27),floorMat);floor.position.y=-.35;floor.receiveShadow=true;scene.add(floor);
// Layered, machined edge around the playfield.
for(const [x,z,sx,sz] of [[0,13.7,39,.32],[0,-13.7,39,.32],[18.7,0,.32,27.7],[-18.7,0,.32,27.7]]){const rail=new THREE.Mesh(new THREE.BoxGeometry(sx,.48,sz),trimMat);rail.position.set(x,-.03,z);rail.castShadow=true;rail.receiveShadow=true;scene.add(rail);const line=new THREE.Mesh(new THREE.BoxGeometry(sx*.86,.035,sz*.3),cyanMat);line.position.set(x,.22,z);scene.add(line)}
// Fine technical floor lines and inset deck plates.
for(let x=-17;x<=17;x+=2){const g=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x,-.068,-13),new THREE.Vector3(x,-.068,13)]);scene.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:x%4===1?0x34545a:0x263e46,transparent:true,opacity:.38})));}
for(let z=-12;z<=12;z+=2){const g=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-18,-.067,z),new THREE.Vector3(18,-.067,z)]);scene.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:0x263e46,transparent:true,opacity:.32})));}
for(let i=0;i<18;i++){let x=(i%6-2.5)*5.5,z=(Math.floor(i/6)-1)*8;const plate=new THREE.Mesh(new THREE.BoxGeometry(4.7,.045,6.8),mat(i%3===0?'#192b31':'#17272d',.7,.45));plate.position.set(x,-.04,z);scene.add(plate);}
// Floating stars beyond the arena.
const starGeo=new THREE.BufferGeometry(),starPts=[];for(let i=0;i<300;i++)starPts.push((Math.random()-.5)*100,Math.random()*40-4,(Math.random()-.5)*100);starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPts,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0x94d8d1,size:.075,transparent:true,opacity:.65})));
function addMesh(geo,material,x,y,z,scale=1){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);if(typeof scale==='number')m.scale.setScalar(scale);else m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
// Raised corner pylons and illuminated runway markings.
for(const [x,z] of [[-17,-12],[17,-12],[-17,12],[17,12]]){addMesh(new THREE.CylinderGeometry(.32,.44,1.7,8),steel,x,.64,z);const p=addMesh(new THREE.SphereGeometry(.12,12,8),cyanMat,x,1.55,z);const pl=new THREE.PointLight(0x54f5d0,3,5);pl.position.copy(p.position);scene.add(pl)}
// Low barrier blocks are physical obstacles; circular bumpers impart a lively rebound.
const bumpers=[[-4,6,1.25],[4,7,1.05],[11,7,1.2],[-12,-1,1.15],[-1,-3,1.25],[6,-7,1.15],[13,-1,1.05],[-8,-8,1.05]];
for(const [x,z,r] of bumpers){const base=addMesh(new THREE.CylinderGeometry(r,r*1.12,.62,32),steel,x,.22,z);const ring=addMesh(new THREE.TorusGeometry(r*.78,.075,8,36),cyanMat,x,.57,z);ring.rotation.x=Math.PI/2;const core=addMesh(new THREE.CylinderGeometry(r*.46,r*.58,.18,24),mat('#1e353c',.3,.7),x,.59,z);const glow=addMesh(new THREE.SphereGeometry(.18,16,12),cyanMat,x,.78,z);}
// Void wells: collidable only as a fall region, with a luminous warning halo.
const pits=[[-7,1,1.05],[2,-.5,1.1],[10,-5,1.15],[-1,-9,1.08],[14,3,.9]];
for(const [x,z,r] of pits){addMesh(new THREE.CylinderGeometry(r*1.45,r*1.45,.09,48),mat('#28343a',.4,.45),x,-.01,z);addMesh(new THREE.CylinderGeometry(r,r,.12,48),mat('#050b10',.3,.2),x,.045,z);const halo=addMesh(new THREE.TorusGeometry(r*1.35,.055,8,48),orangeMat,x,.15,z);halo.rotation.x=Math.PI/2;const inner=addMesh(new THREE.TorusGeometry(r*.73,.025,6,40),mat('#ff9a67',.3,.2,'#ff693b',.8),x,.15,z);inner.rotation.x=Math.PI/2;}
// Energy cores: rotating tetrahedra enclosed in a floating orbital ring.
const coreSpots=[[-10,7],[0,10],[8,2]],cores=[];
for(const [x,z] of coreSpots){const group=new THREE.Group();group.position.set(x,.9,z);scene.add(group);const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.54,0),cyanMat);crystal.castShadow=true;group.add(crystal);const ring=new THREE.Mesh(new THREE.TorusGeometry(.78,.035,8,40),mat('#a7ffe9',.2,.35,'#54f5d0',1.5));ring.rotation.x=Math.PI/2.5;group.add(ring);const halo=new THREE.PointLight(0x54f5d0,3,5);halo.position.set(x,1.2,z);scene.add(halo);cores.push({x,z,group,crystal,active:true});}
// Extraction gate, visible from anywhere in the arena.
const gate=new THREE.Group();gate.position.set(14,.05,-10);scene.add(gate);const gateRing=new THREE.Mesh(new THREE.TorusGeometry(1.35,.13,12,56),cyanMat);gateRing.rotation.x=Math.PI/2;gate.add(gateRing);const gateInner=new THREE.Mesh(new THREE.TorusGeometry(.9,.035,8,48),mat('#aaffeb',.25,.2,'#54f5d0',2));gateInner.rotation.x=Math.PI/2;gate.add(gateInner);const gateBase=new THREE.Mesh(new THREE.CylinderGeometry(1.65,1.8,.22,48),steel);gateBase.position.y=.12;gate.add(gateBase);const gateLight=new THREE.PointLight(0x54f5d0,6,9);gateLight.position.set(14,2,-10);scene.add(gateLight);
// A moving sentry orb adds a readable, avoidable hazard.
const sentry=addMesh(new THREE.IcosahedronGeometry(.48,1),orangeMat,0,.72,-5);const sentryRing=addMesh(new THREE.TorusGeometry(.7,.035,8,30),mat('#ffac85',.3,.2,'#ff6944',1),0,.72,-5);sentryRing.rotation.x=Math.PI/2;
// Player orb: metallic shell, lit seams, and a subtle magnetic shadow.
const player=new THREE.Group();scene.add(player);const sphere=addMesh(new THREE.SphereGeometry(.62,40,28),ballMat,0,0,0);sphere.parent=player;sphere.position.set(0,.62,0);const equator=new THREE.Mesh(new THREE.TorusGeometry(.625,.025,8,48),cyanMat);equator.rotation.x=Math.PI/2;player.add(equator);const meridian=new THREE.Mesh(new THREE.TorusGeometry(.625,.018,8,48),mat('#b4fff0',.2,.3,'#54f5d0',1));player.add(meridian);const shadow=addMesh(new THREE.CircleGeometry(.7,32),new THREE.MeshBasicMaterial({color:0x000000,transparent:true,opacity:.24}),0,.01,0);shadow.rotation.x=-Math.PI/2;shadow.castShadow=false;shadow.parent=player;shadow.position.set(0,.02,0);
const state={running:false,won:false,x:-14,z:9,vx:0,vz:0,lives:3,got:0,time:0,boost:0,invuln:0,checkpoint:{x:-14,z:9},keys:{},toast:0};player.position.set(state.x,0,state.z);
const timerEl=document.querySelector('#timer'),statusEl=document.querySelector('#status'),dots=[...document.querySelectorAll('.dot')],livesEl=document.querySelector('#lives'),toastEl=document.querySelector('#toast'),modal=document.querySelector('#modal');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function toast(text){toastEl.textContent=text;toastEl.classList.add('show');state.toast=1.8}function updateHud(){timerEl.textContent=`${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;dots.forEach((d,i)=>d.classList.toggle('on',i<state.got));livesEl.textContent='◆ '.repeat(state.lives).trim()||'—';}
function start(){if(state.won)return;state.running=true;modal.classList.add('hidden');statusEl.textContent='Collect all 3 energy cores, then reach the extraction gate.';renderer.domElement.focus?.()}
document.querySelector('#playButton').addEventListener('click',()=>{if(state.lives<=0)reset();start()});
function reset(){state.x=-14;state.z=9;state.vx=state.vz=0;state.lives=3;state.got=0;state.time=0;state.boost=0;state.invuln=1;state.checkpoint={x:-14,z:9};state.won=false;cores.forEach(c=>{c.active=true;c.group.visible=true});updateHud();document.querySelector('#modalTitle').textContent='Orbital Drop';document.querySelector('#modalCopy').innerHTML='A little gravity. A lot of momentum.<br>Recover all three cores and find the gate.';document.querySelector('#playButton').innerHTML='DROP IN <span>↗</span>';statusEl.textContent='Collect all 3 energy cores, then reach the extraction gate.'}
function finish(win){state.running=false;state.won=win;modal.classList.remove('hidden');if(win){document.querySelector('#modalTitle').textContent='Clean orbit.';document.querySelector('#modalCopy').innerHTML=`All cores recovered in ${timerEl.textContent}.<br>That was some beautiful momentum.`;document.querySelector('#playButton').innerHTML='RUN IT AGAIN <span>↗</span>';toast('EXTRACTION COMPLETE · SECTOR CLEARED')}else{document.querySelector('#modalTitle').textContent='Lost in the void';document.querySelector('#modalCopy').innerHTML='The field got the better of you.<br>Reset your trajectory and try again.';document.querySelector('#playButton').innerHTML='RETRY RUN <span>↗</span>'}}
function recover(){if(state.lives<=0){finish(false);return}state.lives--;state.x=state.checkpoint.x;state.z=state.checkpoint.z;state.vx=state.vz=0;state.invuln=1.5;player.position.set(state.x,0,state.z);updateHud();toast(state.lives>0?'FIELD RECOIL · CHECKPOINT RESTORED':'CRITICAL · RECOVERY SYSTEM OFFLINE');if(state.lives<=0)setTimeout(()=>{if(!state.running)finish(false)},900)}
const keys=state.keys;addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='r'){reset();start()}if(k===' '&&state.running)boost()});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
for(const button of document.querySelectorAll('.touch-controls button')){const dir=button.dataset.dir;const on=e=>{e.preventDefault();keys[dir]=true;button.classList.add('active');if(dir==='boost')boost()};const off=e=>{e.preventDefault();keys[dir]=false;button.classList.remove('active')};button.addEventListener('pointerdown',on);button.addEventListener('pointerup',off);button.addEventListener('pointercancel',off);button.addEventListener('pointerleave',off)}
function boost(){if(!state.running||state.boost>0)return;const speed=Math.hypot(state.vx,state.vz);if(speed>.2){state.vx+=state.vx/speed*5.2;state.vz+=state.vz/speed*5.2}else state.vz-=5.2;state.boost=1.35;toast('BOOST KICK · MOMENTUM +')}
let last=performance.now();const clock=new THREE.Clock();
function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.033);last=now;const t=now*.001;
  cores.forEach((c,i)=>{if(c.active){c.group.rotation.y=t*1.2+i*.9;c.group.position.y=.9+Math.sin(t*2+i)*.12;c.crystal.rotation.x=t*.55}});gate.rotation.y=Math.sin(t*.8)*.04;gateRing.material=state.got===3?cyanMat:mat('#49746f',.3,.3,'#236f62',.7);gateLight.intensity=state.got===3?8:2.5;const sx=Math.sin(t*1.15)*6.5;sentry.position.set(sx,.72,-5);sentryRing.position.x=sx;sentry.rotation.x=t*.6;sentry.rotation.z=t*.4;
  if(state.running){state.time+=dt;state.boost=Math.max(0,state.boost-dt);state.invuln=Math.max(0,state.invuln-dt);let ix=(keys.d||keys.arrowright||keys.right?1:0)-(keys.a||keys.arrowleft||keys.left?1:0),iz=(keys.s||keys.arrowdown||keys.down?1:0)-(keys.w||keys.arrowup||keys.up?1:0);let mag=Math.hypot(ix,iz);if(mag>0){ix/=mag;iz/=mag;state.vx+=ix*17*dt;state.vz+=iz*17*dt}const speed=Math.hypot(state.vx,state.vz),friction=Math.exp(-1.65*dt);state.vx*=friction;state.vz*=friction;const max=state.boost>0?13:9;if(speed>max){state.vx=state.vx/speed*max;state.vz=state.vz/speed*max}state.x+=state.vx*dt;state.z+=state.vz*dt;
    for(const [x,z,r] of bumpers){const dx=state.x-x,dz=state.z-z,d=Math.hypot(dx,dz),min=r+.68;if(d<min&&d>.001){const nx=dx/d,nz=dz/d;state.x=x+nx*min;state.z=z+nz*min;const dot=state.vx*nx+state.vz*nz;if(dot<0){state.vx-=1.75*dot*nx;state.vz-=1.75*dot*nz}}}
    state.x=clamp(state.x,-17.25,17.25);state.z=clamp(state.z,-12.25,12.25);
    for(const [x,z,r] of pits){if(Math.hypot(state.x-x,state.z-z)<r+.05){recover();break}}
    if(state.invuln<=0&&Math.hypot(state.x-sentry.position.x,state.z-sentry.position.z)<1.02){recover()}
    cores.forEach(c=>{if(c.active&&Math.hypot(state.x-c.x,state.z-c.z)<1.15){c.active=false;c.group.visible=false;state.got++;state.checkpoint={x:c.x-1.25,z:c.z+.8};toast(`ENERGY CORE ${state.got}/3 · CHECKPOINT SET`);statusEl.textContent=state.got===3?'All cores recovered. Reach the extraction gate!':`Energy core ${state.got} of 3 recovered. Keep rolling.`;updateHud()}});
